// Generated by OrchestKit Claude Plugin

// Guards the orank "NLWeb streaming support" recovery: POST /ask must switch to
// SSE (text/event-stream) when the client signals streaming via the RFC 7240
// `Prefer` header, in addition to the existing ?streaming / body / Accept paths.
// doc-search is mocked so the test isolates the streaming-trigger logic.

import { describe, expect, it, vi } from "vitest";

vi.mock("@/lib/doc-search", () => ({
	searchDocs: (_query: string, limit = 10) => Array.from({ length: Math.min(limit, 15) }, (_, i) => ({
		id: String(i), title: `OrchestKit ${i}`, url: `/docs/overview-${i}`, content: "c",
	})),
}));

import { GET, POST } from "@/app/api/ask/route";

function askReq(headers: Record<string, string>): Request {
	return new Request("https://orchestkit.dev/ask", {
		method: "POST",
		headers: { "content-type": "application/json", ...headers },
		body: JSON.stringify({ query: "what is orchestkit" }),
	});
}

describe("/ask result limits", () => {
	it.each([["&limit=2", 2], ["", 10], ["&limit=12", 12]])("honors the bound for %j", async (param, count) => {
		const res = await GET(new Request(`https://orchestkit.dev/ask?query=orchestkit${param}`));
		expect(res.status).toBe(200);
		const body = await res.json();
		expect(body.results).toHaveLength(count);
		expect(body._meta.count).toBe(count);
	});

	it.each(["", "0", "-3", "2.5", "abc", "101"])("rejects invalid limit %j", async (limit) => {
		const res = await GET(new Request(`https://orchestkit.dev/ask?query=orchestkit&limit=${limit}`));
		expect(res.status).toBe(400);
		expect(await res.json()).toMatchObject({ title: "Invalid limit", status: 400 });
	});
});

describe("/ask streaming triggers", () => {
	it("Prefer: streaming → text/event-stream", async () => {
		const res = await POST(askReq({ prefer: "streaming" }));
		expect(res.headers.get("Content-Type")).toBe("text/event-stream; charset=utf-8");
	});

	it("Prefer: respond-async → text/event-stream", async () => {
		const res = await POST(askReq({ prefer: "respond-async" }));
		expect(res.headers.get("Content-Type")).toBe("text/event-stream; charset=utf-8");
	});

	it.each([
		'return=representation; note="respond-async"',
		'return="a; b", wait=5; note="escaped \\" quote, streaming, tail"',
		"return=respond-async; streaming",
		"not-respond-async, streaming-extra",
	])("keeps JSON for Prefer: %s", async (prefer) => {
		const res = await POST(askReq({ prefer }));
		expect(res.status).toBe(200);
		expect(res.headers.get("Content-Type")).toContain("application/json");
	});

	it.each(["ReSpOnD-AsYnC", "StReAmInG"])("streams for a top-level %s in a preference list", async (token) => {
		const res = await POST(askReq({ prefer: `return="a, b; c", ${token}; wait=5` }));
		expect(res.headers.get("Content-Type")).toBe("text/event-stream; charset=utf-8");
	});

	it("streams for the explicit streaming query option without Prefer", async () => {
		const res = await GET(new Request("https://orchestkit.dev/ask?query=hooks&streaming=true"));
		expect(res.headers.get("Content-Type")).toBe("text/event-stream; charset=utf-8");
	});

	it("no streaming signal → JSON with _meta", async () => {
		const res = await POST(askReq({}));
		expect(res.headers.get("Content-Type")).toContain("application/json");
		const body = await res.json();
		expect(body._meta).toBeTruthy();
		expect(body._meta.version).toBeDefined();
	});
});

describe("/ask Accept negotiation", () => {
	const SSE = "text/event-stream; charset=utf-8";
	const get = (accept: string, extra = "") =>
		GET(new Request(`https://orchestkit.dev/ask?query=hooks${extra}`, { headers: { accept } }));

	it.each([
		["application/json", "application/json"],
		["*/*", "application/json"],
		["text/event-stream", SSE],
		["text/event-stream, application/json", SSE],
		["application/json, text/event-stream", SSE],
		["Text/Event-Stream", SSE],
		["TEXT/EVENT-STREAM; charset=utf-8", SSE],
		["text/event-stream;q=0.5, application/json;q=0.5", SSE],
		["application/json, text/event-stream;q=0", "application/json"],
		["application/json, Text/Event-Stream; Q=0", "application/json"],
		["text/event-stream;q=0.000", "application/json"],
		["text/event-stream;q=0.1, application/json", "application/json"],
		["text/event-stream;q=0.5, */*", "application/json"],
		["text/*", "application/json"],
		['application/json; v="a, text/event-stream"', "application/json"],
	])("Accept: %s -> %s", async (accept, type) => {
		const res = await get(accept);
		expect(res.status).toBe(200);
		expect(res.headers.get("Content-Type")).toBe(type);
	});

	it("keeps the explicit query opt-in when Accept rejects SSE", async () => {
		const res = await get("application/json, text/event-stream;q=0", "&streaming=true");
		expect(res.headers.get("Content-Type")).toBe(SSE);
	});

	it.each([
		[{ prefer: "streaming" }, { query: "hooks" }],
		[{}, { query: "hooks", streaming: true }],
		[{}, { query: "hooks", prefer: { streaming: true } }],
	])("keeps the Prefer/body opt-in %j %j when Accept rejects SSE", async (headers, body) => {
		const res = await POST(
			new Request("https://orchestkit.dev/ask", {
				method: "POST",
				headers: { "content-type": "application/json", accept: "application/json, text/event-stream;q=0", ...headers },
				body: JSON.stringify(body),
			}),
		);
		expect(res.headers.get("Content-Type")).toBe(SSE);
	});
});

// A bare probe (no `query`) must return a 200 NLWeb envelope, not a 400 — a 400
// reads to agent-readiness scanners as "no NLWeb endpoint here".
describe("/ask no-query probe → 200 NLWeb envelope", () => {
	it("GET /ask with no query → 200, empty results, usage hint", async () => {
		const res = await GET(new Request("https://orchestkit.dev/ask"));
		expect(res.status).toBe(200);
		expect(res.headers.get("Content-Type")).toContain("application/json");
		const body = await res.json();
		expect(body.results).toEqual([]);
		expect(body._meta.response_type).toBe("list");
		expect(body._meta.version).toBeDefined();
		expect(body._meta.count).toBe(0);
		expect(typeof body._meta.usage).toBe("string");
		expect(body._meta.usage.length).toBeGreaterThan(0);
	});

	it("POST /ask with empty query → 200, empty results", async () => {
		const res = await POST(
			new Request("https://orchestkit.dev/ask", {
				method: "POST",
				headers: { "content-type": "application/json" },
				body: JSON.stringify({ query: "   " }),
			}),
		);
		expect(res.status).toBe(200);
		const body = await res.json();
		expect(body.results).toEqual([]);
		expect(body._meta.count).toBe(0);
		expect(typeof body._meta.usage).toBe("string");
	});

	it.each([undefined, ""])("POST /ask with empty body %j → 200 envelope", async (requestBody) => {
		const res = await POST(
			new Request("https://orchestkit.dev/ask", {
				method: "POST",
				headers: { "content-type": "application/json" },
				body: requestBody,
			}),
		);
		expect(res.status).toBe(200);
		const body = await res.json();
		expect(body.results).toEqual([]);
		expect(body._meta.count).toBe(0);
		expect(typeof body._meta.usage).toBe("string");
	});
});

describe("/ask request bodies", () => {
	it.each(['{"query":"hooks"', "   "])("rejects malformed JSON %j with a JSON problem", async (body) => {
		const res = await POST(new Request("https://orchestkit.dev/ask", {
			method: "POST",
			headers: { "content-type": "application/json" },
			body,
		}));
		expect(res.status).toBe(400);
		expect(res.headers.get("Content-Type")).toContain("application/json");
		expect(await res.json()).toMatchObject({
			type: "about:blank",
			title: "Invalid JSON body",
			status: 400,
			detail: expect.any(String),
			instance: "/ask",
		});
	});

	it("still honors a URL query when JSON parsing fails", async () => {
		const res = await POST(new Request("https://orchestkit.dev/ask?query=hooks&limit=1", {
			method: "POST",
			headers: { "content-type": "application/json" },
			body: '{"query":"ignored"',
		}));
		expect(res.status).toBe(200);
		expect(await res.json()).toMatchObject({ query: "hooks", _meta: { count: 1 } });
	});

	it("still accepts a form-encoded query", async () => {
		const res = await POST(new Request("https://orchestkit.dev/ask", {
			method: "POST",
			body: new URLSearchParams({ query: "hooks" }),
		}));
		expect(res.status).toBe(200);
		expect(await res.json()).toMatchObject({ query: "hooks" });
	});
});

// NLWeb's canonical request body is { query: { text: "..." } } — the shape
// agent-readiness scanners (orank) actually probe with. The route previously
// read `query` as a string and 500'd on the object form, which the scanner read
// as "no /ask endpoint found".
describe("/ask NLWeb canonical body { query: { text } }", () => {
	function nlwebReq(headers: Record<string, string> = {}): Request {
		return new Request("https://orchestkit.dev/ask", {
			method: "POST",
			headers: { "content-type": "application/json", ...headers },
			body: JSON.stringify({ query: { text: "what is orchestkit" } }),
		});
	}

	it("POST with query.text → 200 JSON with _meta + results (not 500)", async () => {
		const res = await POST(nlwebReq());
		expect(res.status).toBe(200);
		expect(res.headers.get("Content-Type")).toContain("application/json");
		const body = await res.json();
		expect(body._meta.response_type).toBeDefined();
		expect(body._meta.version).toBeDefined();
		expect(body.results.length).toBeGreaterThan(0);
	});

	it("query.text + Accept: text/event-stream → SSE (streaming check)", async () => {
		const res = await POST(nlwebReq({ accept: "text/event-stream" }));
		expect(res.headers.get("Content-Type")).toBe(
			"text/event-stream; charset=utf-8",
		);
	});
});

describe("/ask JSON query validation", () => {
	function postJson(body: Record<string, unknown>): Promise<Response> {
		return POST(new Request("https://orchestkit.dev/ask", {
			method: "POST",
			headers: { "content-type": "application/json" },
			body: JSON.stringify(body),
		}));
	}

	it.each([
		{ query: 7 },
		{ query: ["hooks"] },
		{ query: { text: 7 } },
		{ query: { text: ["hooks"] } },
		{ query: { text: { value: "hooks" } } },
		{ q: false },
		{ question: ["hooks"] },
	])("rejects a mistyped query in %j with a JSON problem", async (body) => {
		const res = await postJson(body);
		expect(res.status).toBe(400);
		expect(res.headers.get("Content-Type")).toContain("application/json");
		expect(await res.json()).toMatchObject({
			type: "about:blank",
			title: "Invalid query",
			status: 400,
			instance: "/ask",
		});
	});

	it.each([{ q: "hooks" }, { question: "hooks" }])("accepts a string alias in %j", async (body) => {
		const res = await postJson(body);
		expect(res.status).toBe(200);
		expect(await res.json()).toMatchObject({ query: "hooks" });
	});

	it.each([
		{},
		{ query: null },
		{ query: {} },
		{ query: { text: null } },
		{ q: null },
	])("preserves the 200 probe for an absent query in %j", async (body) => {
		const res = await postJson(body);
		expect(res.status).toBe(200);
		expect(await res.json()).toMatchObject({ query: "", results: [] });
	});
});
